  "alphabetically": [{ en: "The books are arranged alphabetically.", zh: "这些书按字母顺序排列。" }, { en: "Sort the list alphabetically by surname.", zh: "按姓氏字母顺序排列名单。" }],
  "alteration": [{ en: "The small alteration to the plan made it fairer for everyone.", zh: "对计划的微调让它对所有人都更公平。" }, { en: "The tailor's alteration gave the dress a softer shape.", zh: "裁缝的修改让裙子轮廓更柔和。" }],
