  "alternatively": [{ en: "Take the bus, or alternatively walk along the river.", zh: "可以坐公交，或者沿着河走。" }, { en: "Alternatively, you can send an email.", zh: "另一种办法是你可以发邮件。" }],
  "altitude": [{ en: "At high altitude the air feels thin and cool.", zh: "高海拔处空气稀薄而凉。" }, { en: "The plane rose to a safe altitude quickly.", zh: "飞机很快升到了安全高度。" }],
