  "ambiguity": [{ en: "The ambiguity in the question confused the class.", zh: "问题中的含糊让全班困惑。" }, { en: "Good writing removes ambiguity for the reader.", zh: "好文章为读者消除歧义。" }],
  "ambiguous": [{ en: "The instructions were ambiguous, so we asked.", zh: "说明含糊不清，于是我们提问。" }, { en: "Avoid ambiguous words in your report.", zh: "报告中避免使用模棱两可的词。" }],
