  "amy": [{ en: "Amy is a kind girl.", zh: "艾米是个善良的女孩。" }, { en: "Amy reads a warm book.", zh: "艾米读着一本温暖的书。" }],
  "analogous": [{ en: "A wing is analogous to a bird's arm.", zh: "机翼类似于鸟的翅膀。" }, { en: "The two problems are analogous in structure.", zh: "这两个问题在结构上相似。" }],
  "analogue": [{ en: "This is an analogue clock, not a digital one.", zh: "这是机械钟，不是电子钟。" }, { en: "The old camera uses analogue film.", zh: "这台老相机使用胶片。" }],
