  "cater": [{ en: "The kitchen will cater lunch for the sports day.", zh: "厨房将为运动会供应午餐。" }, { en: "The club caters to students who love chess.", zh: "这个社团服务于热爱国际象棋的学生。" }],
  "cathedral": [{ en: "The ancient cathedral has a tall gray tower.", zh: "古老的大教堂有高高的灰塔。" }, { en: "We visited a famous cathedral on the trip.", zh: "旅行中我们参观了著名的大教堂。" }],
  "catholic": [{ en: "She is a practicing catholic believer.", zh: "她是一位虔诚的天主教徒。" }, { en: "He has a catholic interest in books.", zh: "他对书籍有广泛的兴趣。" }],
  "cathy": [{ en: "Cathy is a bright student.", zh: "凯茜是个聪明的学生。" }, { en: "Cathy keeps a warm smile.", zh: "凯茜保持温暖微笑。" }],
  "causal": [{ en: "We found the causal link between rest and clear thinking.", zh: "我们发现了休息与清晰思维之间的因果关系。" }, { en: "The chart shows a simple causal pattern for the rain.", zh: "图表显示了关于雨的简单因果模式。" }],
  "caution": [{ en: "Cross the street with great caution.", zh: "过马路时要格外小心。" }, { en: "The sign is a caution about the wet floor.", zh: "这个标志警告地面湿滑。" }],
  "cautious": [{ en: "Be cautious when crossing the busy road.", zh: "过繁忙的马路时要小心。" }, { en: "A cautious driver always checks the mirrors.", zh: "谨慎的司机总会查看后视镜。" }],
  "cavity": [{ en: "The dentist found a small cavity in my tooth.", zh: "牙医在我牙上发现一个小洞。" }, { en: "Brushing helps prevent a cavity from forming.", zh: "刷牙有助于防止蛀洞形成。" }],
