  "cellar": [{ en: "The old cellar stays cool in the summer.", zh: "旧地窖夏天也很凉。" }, { en: "We store the winter boxes in the cellar.", zh: "我们把冬天的箱子放在地下室。" }],
  "cellphone": [{ en: "I left my cellphone in the classroom.", zh: "我把手机落在教室里了。" }, { en: "Turn off your cellphone during the exam.", zh: "考试期间请关掉手机。" }],
  "cement": [{ en: "The workers laid cement for the new path.", zh: "工人为新小路铺了水泥。" }, { en: "Shared interests cement our friendship.", zh: "共同的兴趣巩固了我们的友谊。" }],
  "censor": [{ en: "The school censors films before showing them.", zh: "学校在放映电影前会先审查。" }, { en: "Officials censored part of the report.", zh: "官员删改了报告的一部分。" }],
  "census": [{ en: "A census counts how many people live in a town.", zh: "人口普查统计镇上住了多少人。" }, { en: "We learned how a census helps plan new schools.", zh: "我们学习了人口普查如何帮助规划新学校。" }],
  "centigrade": [{ en: "Water boils at 100 degrees centigrade.", zh: "水在摄氏100度沸腾。" }, { en: "The room is twenty degrees centigrade.", zh: "房间温度是摄氏二十度。" }],
  "centralize": [{ en: "The school centralized its records.", zh: "学校把档案集中管理。" }, { en: "They plan to centralize the buying process.", zh: "他们计划把采购流程集中化。" }],
  "cereal": [{ en: "I had cereal with milk for breakfast.", zh: "我早餐吃了麦片加牛奶。" }, { en: "This cereal is made from whole grains.", zh: "这种谷物食品由全谷物制成。" }],
  "certainty": [{ en: "We can say with certainty that the answer is right.", zh: "我们可以肯定这个答案是对的。" }, { en: "She faced the test with certainty and calm.", zh: "她带着把握和冷静面对考试。" }],
  "certify": [{ en: "The teacher will certify that the work is original.", zh: "老师会证明这份作业是原创的。" }, { en: "A doctor certifies that the player is healthy.", zh: "医生证明选手身体健康。" }],
  "chamber": [{ en: "The sound echoed in the chamber.", zh: "声音在房间里回荡。" }, { en: "The doctor checked the chamber of the heart.", zh: "医生检查了心脏的腔室。" }],
  "champagne": [{ en: "Her dress is champagne gold.", zh: "她的裙子是香槟金色。" }],
  "chancellor": [{ en: "The chancellor opened the new university building.", zh: "校长为新大学楼揭幕。" }, { en: "The chancellor spoke about funding for schools.", zh: "总理谈到了对学校的拨款。" }],
  "changeable": [{ en: "The weather here is very changeable.", zh: "这里的天气变化很大。" }, { en: "He has a changeable mood.", zh: "他的心情变化无常。" }],
