  "chap": [{ en: "The young chap carried the boxes.", zh: "那个小伙子搬了箱子。" }, { en: "He is a decent chap to work with.", zh: "他是个很好共事的人。" }],
  "characterize": [{ en: "We characterize our class as friendly and hardworking.", zh: "我们把班级描述为友好而勤奋的。" }, { en: "Kindness is what characterizes a good teammate.", zh: "善良是好队友的典型特征。" }],
  "charcoal": [{ en: "We drew the landscape with charcoal in art class.", zh: "美术课上我们用木炭画风景。" }, { en: "Charcoal burns slowly and gives steady heat.", zh: "木炭燃烧缓慢，供热稳定。" }],
  "charter": [{ en: "Our club received a charter from the school.", zh: "学校给我们社团颁发了许可证。" }, { en: "We read the charter of student rights.", zh: "我们阅读了学生权利宪章。" }],
  "chasm": [{ en: "A deep chasm split the valley.", zh: "一道深谷把山谷分开。" }, { en: "There is a chasm between the two plans.", zh: "这两个方案之间差距很大。" }],
