  "chick": [{ en: "A yellow chick followed its mother across the yard.", zh: "黄色小鸡跟着妈妈穿过院子。" }, { en: "We watched an egg hatch into a chick.", zh: "我们看蛋孵出小鸡。" }],
  "childish": [{ en: "It was childish to laugh at his mistake.", zh: "嘲笑他的错误很幼稚。" }, { en: "Her childish joy was easy to see.", zh: "她的孩子气的快乐显而易见。" }],
  "chill": [{ en: "A morning chill made us wear jackets.", zh: "清晨的寒意让我们穿上了外套。" }, { en: "The cool breeze gave a pleasant chill.", zh: "凉风带来舒适的清爽。" }],
  "chimney": [{ en: "Smoke rises from the old brick chimney.", zh: "烟从旧砖烟囱升起。" }, { en: "We drew a house with a tall chimney in art class.", zh: "美术课上我们画了带高烟囱的房子。" }],
  "chiwen": [{ en: "The chiwen is a small roof figure.", zh: "吻兽是屋顶上的小雕像。" }, { en: "We learned the chiwen word today.", zh: "我们今天学了吻兽这个词。" }],
  "choir": [{ en: "Our school choir sang at the opening ceremony.", zh: "校合唱团在开幕式上演唱。" }, { en: "She joined the choir last autumn.", zh: "去年秋天她加入了合唱团。" }],
  "chop": [{ en: "Mom will chop the vegetables for dinner.", zh: "妈妈会为晚饭切菜。" }, { en: "Please chop the green onions finely.", zh: "请把葱花切细。" }],
  "chord": [{ en: "She played a soft chord on the guitar.", zh: "她在吉他上弹了一个柔和的和弦。" }, { en: "The piano chord sounded bright and clear.", zh: "钢琴和弦听起来明亮清晰。" }],
  "chromosome": [{ en: "Each cell has pairs of chromosomes.", zh: "每个细胞都有成对的染色体。" }, { en: "The chromosome carries genetic information.", zh: "染色体携带遗传信息。" }],
  "chronic": [{ en: "He has a chronic cough in winter.", zh: "他冬天有慢性咳嗽。" }, { en: "Chronic tiredness means you need more rest.", zh: "长期疲劳意味着你需要更多休息。" }],
  "chronicle": [{ en: "The old chronicle told the story of the first school.", zh: "旧编年史讲述了第一所学校的故事。" }, { en: "We kept a small class chronicle for the year's events.", zh: "我们保留了一本记录年度事件的小班级编年史。" }],
  "cigar": [{ en: "The old cigar box is now a pencil case.", zh: "旧雪茄盒现在成了铅笔盒。" }, { en: "We learned that cigars are harmful to health.", zh: "我们了解到雪茄有害健康。" }],
  "cigaret": [{ en: "He put out the cigaret.", zh: "他掐灭了香烟。" }, { en: "A cigaret lay on the table.", zh: "桌上放着一支香烟。" }],
  "cindy": [{ en: "Cindy is our class helper.", zh: "辛迪是我们的班级助手。" }, { en: "Cindy sings a warm song.", zh: "辛迪唱了一首温暖的歌。" }],
  "circular": [{ en: "We walked around the circular track twice.", zh: "我们绕圆形跑道走了两圈。" }, { en: "The school sent a circular about the holiday.", zh: "学校发了关于假期的通知。" }],
  "circulate": [{ en: "Fresh air circulates through the open windows.", zh: "新鲜空气从敞开的窗户流通进来。" }, { en: "The teacher circulated the papers to each row.", zh: "老师把试卷逐排传下去。" }],
  "circulation": [{ en: "Exercise improves blood circulation in your body.", zh: "运动促进身体的血液循环。" }, { en: "The magazine has a large circulation among students.", zh: "这本杂志在学生中发行量很大。" }],
  "circumference": [{ en: "The circumference of the circle is ten metres.", zh: "这个圆的周长是十米。" }, { en: "Measure the circumference of your wrist.", zh: "量一下你手腕的周长。" }],
  "civility": [{ en: "He answered with civility even when tired.", zh: "即使累了，他回答时仍很有礼貌。" }, { en: "Civility makes daily life easier.", zh: "礼貌让日常生活更顺畅。" }],
  "civilize": [{ en: "Trade helped civilize the frontier.", zh: "贸易促进了边疆地区的文明化。" }, { en: "They hoped education would civilize the region.", zh: "他们希望教育能使这个地区文明起来。" }],
  "claire": [{ en: "Claire is a kind helper.", zh: "克莱儿是个友善的帮手。" }, { en: "Claire sings a warm song.", zh: "克莱儿唱了一首温暖的歌。" }],
