  "hardware": [{ en: "The computer hardware includes the screen and keyboard.", zh: "计算机硬件包括屏幕和键盘。" }, { en: "The store sells hardware for home repairs.", zh: "这家店出售家用维修五金。" }],
  "hardworking": [{ en: "He is a hardworking student.", zh: "他是个勤奋的学生。" }, { en: "The hardworking team finished early.", zh: "勤奋的团队提前完成了。" }],
  "hardy": [{ en: "Hardy plants survive cold winters.", zh: "耐寒的植物能熬过严冬。" }, { en: "The hardy farmers worked through the storm.", zh: "坚韧的农民顶着暴风雨干活。" }],
  "hare": [{ en: "A hare ran across the field.", zh: "一只野兔跑过田野。" }, { en: "The hare escaped into the bushes.", zh: "野兔逃进了灌木丛。" }],
  "harmless": [{ en: "The plastic snake is harmless and just a toy.", zh: "塑料蛇无害，只是玩具。" }, { en: "His mistake was harmless and easy to fix.", zh: "他的错误无恶意，容易改正。" }],
