  "harp": [{ en: "She plays the harp in the school band.", zh: "她在校乐队里弹竖琴。" }, { en: "The harp has many strings.", zh: "竖琴有很多根弦。" }],
  "harsh": [{ en: "The harsh wind made our cheeks red.", zh: "凛冽的风把我们的脸吹红了。" }, { en: "His harsh words hurt his classmate's feelings.", zh: "他严厉的话伤了同学的心。" }],
  "hassle": [{ en: "Booking tickets was a hassle.", zh: "订票是件麻烦事。" }, { en: "They had a hassle over money.", zh: "他们为钱发生了争执。" }],
