  "honorable": [{ en: "Helping a classmate is an honorable act.", zh: "帮助同学是光荣的行为。" }, { en: "The team lost, but fought an honorable match.", zh: "队伍输了，但打了一场体面的比赛。" }],
  "honourable": [{ en: "It was an honourable decision.", zh: "这是个值得尊敬的决定。" }, { en: "He is an honourable man who keeps promises.", zh: "他是个守信的可敬之人。" }],
