  "infectious": [{ en: "A bright smile can be infectious in class.", zh: "灿烂的笑容在班上很有感染力。" }, { en: "Washing hands limits infectious germs.", zh: "洗手能减少传染性病菌。" }],
  "infer": [{ en: "We can infer the answer from the clues.", zh: "我们可以从线索中推断出答案。" }, { en: "What can you infer from this story?", zh: "从这个故事你能推断出什么？" }],
  "inference": [{ en: "The small inference came from the new chart.", zh: "小推论来自新图表。" }, { en: "The kind plan gave a warm inference for the class.", zh: "善良的计划给班级带来温暖的推论。" }],
  "inferior": [{ en: "This product is not inferior to the famous brand.", zh: "这个产品不比名牌差。" }, { en: "Never feel inferior to anyone in your class.", zh: "在班上绝不要觉得自己低人一等。" }],
  "inferiority": [{ en: "He struggled with feelings of inferiority.", zh: "他一直与自卑感抗争。" }, { en: "Comparing yourself to others can create inferiority.", zh: "和别人比较容易产生自卑。" }],
  "infinite": [{ en: "The night sky seems to hold infinite stars.", zh: "夜空似乎有无数的星星。" }, { en: "There is infinite patience in a good teacher.", zh: "好老师有无穷的耐心。" }],
  "infinitely": [{ en: "The night sky seems infinitely large.", zh: "夜空似乎无限广阔。" }, { en: "She is infinitely patient with beginners.", zh: "她对初学者无比耐心。" }],
  "infinity": [{ en: "The stars seem to stretch to infinity.", zh: "星星仿佛一直延伸到无限远处。" }, { en: "The number series goes on to infinity.", zh: "这个数列一直延伸到无穷。" }],
  "inflate": [{ en: "Please inflate the pool ring before we swim.", zh: "下水前请把游泳圈充气。" }, { en: "The story inflates a small mistake into a big problem.", zh: "故事把一个小错误夸大成大问题。" }],
