  "infusion": [{ en: "A hot infusion of herbs helps a cough.", zh: "热草药茶对咳嗽有帮助。" }, { en: "The tea infusion needs five minutes.", zh: "这杯茶需要泡五分钟。" }],
  "ingenious": [{ en: "The engineer found an ingenious solution.", zh: "工程师想出了一个巧妙的方案。" }, { en: "It was an ingenious way to save water.", zh: "这是个节省用水的巧妙办法。" }],
  "ingenuity": [{ en: "Her ingenuity solved the storage problem.", zh: "她的巧思解决了收纳问题。" }, { en: "The design shows real ingenuity.", zh: "这个设计体现了真正的巧思。" }],
