  "injection": [{ en: "The injection was quick and the nurse was gentle.", zh: "打针很快，护士也很温柔。" }, { en: "An injection can prevent some illnesses.", zh: "注射能预防某些疾病。" }],
  "inland": [{ en: "The town lies inland from the coast.", zh: "这座小镇位于内陆，离海岸较远。" }, { en: "Inland areas are usually drier.", zh: "内陆地区通常更干燥。" }],
