  "innate": [{ en: "She has an innate sense of rhythm.", zh: "她天生有节奏感。" }, { en: "Curiosity seems innate in young children.", zh: "好奇心似乎是幼儿天生的。" }],
  "innovate": [{ en: "The company innovates every year.", zh: "这家公司每年都创新。" }, { en: "Small firms often innovate faster.", zh: "小公司往往创新更快。" }],
