  "miniskirt": [{ en: "The shop sells miniskirts in summer.", zh: "这家店夏天卖超短裙。" }, { en: "She wore a red miniskirt to the party.", zh: "她穿着红色超短裙去参加聚会。" }],
  "ministry": [{ en: "The ministry published new rules for schools.", zh: "教育部发布了学校新规定。" }, { en: "We wrote a letter to the ministry about parks.", zh: "我们给部里写了封关于公园的信。" }],
  "mint": [{ en: "The mint tea tastes fresh and cool in summer.", zh: "薄荷茶在夏天尝起来清新清凉。" }, { en: "We grew mint at home and used it in the salad.", zh: "我们在家种薄荷，把它加进沙拉里。" }],
