  "necktie": [{ en: "He wore a blue necktie to the interview.", zh: "他系着蓝色领带去面试。" }, { en: "The necktie matches his shirt.", zh: "领带和他的衬衫很配。" }],
  "needless": [{ en: "Needless worry kept her awake at night.", zh: "不必要的担忧让她夜里睡不着。" }, { en: "It is needless to argue about the weather.", zh: "为天气争论是没有必要的。" }],
  "neglect": [{ en: "Do not neglect your daily reading practice.", zh: "不要忽视每天的阅读练习。" }, { en: "Neglect of the plants made them wilt.", zh: "疏于照料让植物枯萎了。" }],
  "negligent": [{ en: "He was negligent about locking the door.", zh: "他锁门时疏忽大意。" }, { en: "The court found the driver negligent.", zh: "法庭认定司机有过失。" }],
  "negligible": [{ en: "The difference in cost is negligible.", zh: "成本上的差别可以忽略不计。" }, { en: "The risk was negligible and we went ahead.", zh: "风险可以忽略，我们就继续了。" }],
  "negotiation": [{ en: "The negotiation between the two teams was friendly.", zh: "两支团队之间的谈判非常友好。" }, { en: "A calm negotiation helps everyone find a good answer.", zh: "冷静的谈判有助于大家找到好答案。" }],
  "nervously": [{ en: "He waited nervously for the results.", zh: "他紧张地等待结果。" }, { en: "She tapped her pen nervously before the speech.", zh: "演讲前她紧张地敲着笔。" }],
  "neurology": [{ en: "He specialises in neurology.", zh: "他专攻神经病学。" }, { en: "Neurology deals with the nervous system.", zh: "神经病学研究神经系统。" }],
  "neuron": [{ en: "A neuron sends signals in the brain.", zh: "神经元在大脑中传递信号。" }, { en: "The brain has billions of neurons.", zh: "大脑中有数十亿个神经元。" }],
  "neutral": [{ en: "Gray is a neutral color that goes with everything.", zh: "灰色是能搭配一切的中性色。" }, { en: "The referee stayed neutral during the match.", zh: "裁判在比赛中保持中立。" }],
  "neutron": [{ en: "A neutron has no electric charge.", zh: "中子不带电荷。" }, { en: "The lab studied how neutrons move.", zh: "实验室研究了中子的运动方式。" }],
  "newly": [{ en: "Our newly built library opened last week.", zh: "我们新建的图书馆上周开放了。" }, { en: "She welcomed the newly joined class members.", zh: "她欢迎新加入的班级成员。" }],
  "nicely": [{ en: "The room was nicely decorated for the party.", zh: "房间为派对装饰得很漂亮。" }, { en: "She neatly and nicely organized the shelves.", zh: "她把书架整理得又整洁又漂亮。" }],
  "nickel": [{ en: "The coin is an old nickel from long ago.", zh: "这枚硬币是很久以前的镍币。" }, { en: "Nickel is a metal used in some coins.", zh: "镍是某些硬币使用的金属。" }],
  "nickname": [{ en: "Her nickname in class is Sunshine.", zh: "她在班上的昵称是小太阳。" }, { en: "We gave the new puppy a funny nickname.", zh: "我们给小狗取了个有趣的绰号。" }],
  "nitrogen": [{ en: "Most of the air around us is nitrogen.", zh: "我们周围的大部分空气是氮气。" }, { en: "Plants take nitrogen from the soil to grow.", zh: "植物从土壤中吸收氮来生长。" }],
  "noisily": [{ en: "The children played noisily in the yard.", zh: "孩子们在院子里吵闹地玩。" }, { en: "The truck noisily climbed the hill.", zh: "卡车轰鸣着爬上山坡。" }],
  "nominal": [{ en: "He paid a nominal fee for the course.", zh: "他只为这门课付了象征性的一点费用。" }, { en: "The nominal leader had little power.", zh: "名义上的领导人权力很小。" }],
  "nominate": [{ en: "We will nominate two reps for the meeting.", zh: "我们将提名两名代表参会。" }, { en: "She was nominated for the student council.", zh: "她被提名为学生会候选人。" }],
  "nonetheless": [{ en: "The task was hard, and we finished it nonetheless.", zh: "任务很难，但我们还是完成了。" }, { en: "It rained; the game continued nonetheless.", zh: "下雨了，比赛仍照常进行。" }],
  "nonsense": [{ en: "The silly joke was just nonsense, not mean.", zh: "这个傻笑话只是胡闹，没有恶意。" }, { en: "Putting shoes on the desk is nonsense in class.", zh: "把鞋子放课桌上是胡来。" }],
  "norm": [{ en: "Reading every day is a good norm in our class.", zh: "每天阅读是我们班的好习惯。" }, { en: "Finishing homework on time is the norm here.", zh: "按时完成作业在这里是常态。" }],
  "normalization": [{ en: "The two countries moved toward normalization.", zh: "两国朝着关系正常化迈进。" }, { en: "Normalization of the data took a day.", zh: "数据的归一化花了一天。" }],
  "northeast": [{ en: "The wind blew from the northeast all day.", zh: "一整天风都从东北吹来。" }, { en: "Our town lies northeast of the lake.", zh: "我们镇位于湖的东北方。" }],
  "northward": [{ en: "The birds flew northward in spring.", zh: "春天鸟儿向北飞去。" }, { en: "They walked northward along the river.", zh: "他们沿着河向北走。" }],
  "northwards": [{ en: "The geese flew northwards in spring.", zh: "春天大雁向北飞。" }, { en: "They travelled northwards along the coast.", zh: "他们沿着海岸向北行进。" }],
  "northwest": [{ en: "Our school lies to the northwest of the park.", zh: "我们学校在公园的西北方。" }, { en: "A cold wind blew from the northwest.", zh: "西北方向吹来一阵冷风。" }],
  "notable": [{ en: "She made notable progress in her writing.", zh: "她的写作取得了显著进步。" }, { en: "The museum shows notable works by young artists.", zh: "博物馆展出了年轻艺术家的杰出作品。" }],
  "notation": [{ en: "Music notation shows how to play each note.", zh: "乐谱记号表示每个音该怎么演奏。" }, { en: "The teacher wrote the answer in decimal notation.", zh: "老师用十进制写法写出了答案。" }],
  "noteworthy": [{ en: "Her improvement in maths is noteworthy.", zh: "她数学的进步值得注意。" }, { en: "Nothing noteworthy happened on the trip.", zh: "旅途中没有发生值得注意的事。" }],
  "noticeable": [{ en: "Her progress made a noticeable change in the class.", zh: "她的进步给全班带来了明显的变化。" }, { en: "The new bell has a noticeable bright sound.", zh: "新铃铛有响亮的声音。" }],
  "notification": [{ en: "I got a notification about the meeting.", zh: "我收到了关于会议的通知。" }, { en: "Turn off notifications during class.", zh: "上课时关掉通知。" }],
  "notify": [{ en: "Please notify the teacher if you are absent.", zh: "缺席请通知老师。" }, { en: "The school will notify parents about the show.", zh: "学校会通知家长演出的事。" }],
  "notorious": [{ en: "The steep hill is notorious among our cyclists.", zh: "这条陡坡在骑行者中出了名的难。" }, { en: "The lazy cat became notorious for sleeping all day.", zh: "这只懒猫因整天睡觉而出名。" }],
  "notwithstanding": [{ en: "Notwithstanding the rain, the match went on.", zh: "尽管下雨，比赛还是继续。" }, { en: "She finished the work, notwithstanding her illness.", zh: "尽管生病，她还是完成了工作。" }],
