  "noun": [{ en: "A noun names a person, place or thing.", zh: "名词表示人、地点或事物。" }, { en: "Underline each noun in the sentence.", zh: "划出句子里的每个名词。" }],
  "nourish": [{ en: "Fresh food nourishes the body well.", zh: "新鲜食物能很好地滋养身体。" }, { en: "Rain nourished the young plants.", zh: "雨水滋养了幼苗。" }],
  "nourishment": [{ en: "Rice gives the body good nourishment.", zh: "米饭为身体提供良好的营养。" }, { en: "The soil provides nourishment for the plants.", zh: "土壤为植物提供养分。" }],
  "novelty": [{ en: "The novelty of the new game wore off in a week.", zh: "新游戏的新鲜感一周就没了。" }, { en: "Each day brought a small novelty to the class.", zh: "每天班里都有小新鲜事。" }],
  "nucleus": [{ en: "The nucleus sits at the center of the atom.", zh: "原子核位于原子的中心。" }, { en: "Our study group is the nucleus of the class project.", zh: "我们学习小组是班级项目的核心。" }],
  "nuisance": [{ en: "The loud radio was a small nuisance during the quiet hour.", zh: "安静的时段里，大音量的收音机有点打扰。" }, { en: "We fixed the creaking door, and the nuisance stopped.", zh: "我们修好了吱呀的门，困扰消失了。" }],
  "numb": [{ en: "Her fingers were numb from the cold.", zh: "她的手冻得发麻。" }],
  "numerical": [{ en: "Put the data in numerical order.", zh: "把数据按数字顺序排列。" }, { en: "The class learned numerical patterns this week.", zh: "这周全班学了数字规律。" }],
  "nun": [{ en: "The old nun taught children to read kindly.", zh: "老修女和蔼地教孩子们读书。" }, { en: "We read a story about a kind nun in class.", zh: "课堂上我们读了一个善良修女的故事。" }],
  "nurture": [{ en: "Parents nurture their children with care.", zh: "父母用心养育孩子。" }, { en: "Our teacher nurtures a love of science in us.", zh: "老师培养我们对科学的热爱。" }],
  "nutrient": [{ en: "Soil gives plants nutrients.", zh: "土壤给植物提供养分。" }],
  "nylon": [{ en: "The bag is made of strong nylon fabric.", zh: "袋子由结实的尼龙布制成。" }, { en: "We compared the softness of cotton and nylon in class.", zh: "课堂上我们比较了棉和尼龙的柔软度。" }],
  "o'clock": [{ en: "The clock shows two o'clock.", zh: "钟显示两点钟。" }, { en: "We ate at noon o'clock.", zh: "我们中午吃饭。" }],
  "oak": [{ en: "A huge oak tree shades our playground.", zh: "一棵大橡树为操场遮阴。" }, { en: "The bench is made of strong oak.", zh: "这张长椅是结实的橡木做的。" }],
  "oar": [{ en: "He pulled hard on the oar.", zh: "他用力划桨。" }, { en: "One oar fell into the water.", zh: "一支桨掉进了水里。" }],
