  "outlet": [{ en: "Plug the lamp into the outlet safely.", zh: "把台灯安全地插进插座。" }, { en: "The park is a great outlet for our energy.", zh: "公园是我们释放精力的好去处。" }],
  "outrage": [{ en: "The decision caused public outrage.", zh: "这个决定引起了公愤。" }, { en: "She was filled with outrage.", zh: "她满腔愤怒。" }],
