  "outwards": [{ en: "The door opens outwards.", zh: "这扇门向外开。" }, { en: "The roots spread outwards from the tree.", zh: "根系从树向外伸展。" }],
  "oval": [{ en: "Draw an oval around the correct answer.", zh: "把正确答案用椭圆圈起来。" }, { en: "The egg has a gentle oval shape.", zh: "鸡蛋呈柔和的椭圆形。" }],
