  "partnership": [{ en: "Their partnership in the project made it a success.", zh: "他们在项目中的合作使项目获得了成功。" }, { en: "We started a partnership to sell handmade cards.", zh: "我们开始合作销售手工卡片。" }],
  "passerby": [{ en: "A passerby told us the way to the station.", zh: "一位过路人告诉我们去车站的路。" }, { en: "A passerby noticed the loose tile.", zh: "一位路人注意到了松动的瓦片。" }],
