  "pastime": [{ en: "Reading is his favorite pastime.", zh: "阅读是他最喜欢的消遣。" }, { en: "Fishing is a popular pastime here.", zh: "钓鱼是这里很受欢迎的消遣。" }],
  "pasture": [{ en: "Sheep grazed quietly in the green pasture.", zh: "羊在绿色牧场上安静地吃草。" }, { en: "The horses were led to the pasture at noon.", zh: "中午马被牵到了牧场。" }],
  "pat": [{ en: "She gave the dog a gentle pat.", zh: "她轻轻拍了拍狗。" }, { en: "A pat on the back helped him keep going.", zh: "一句夸奖让他继续前行。" }],
  "patch": [{ en: "Dad put a patch on my torn jacket.", zh: "爸爸在我破了的外套上打了个补丁。" }, { en: "A small patch of flowers grows by the gate.", zh: "大门旁有一小片花。" }],
  "paternal": [{ en: "He felt a paternal concern for the students.", zh: "他对学生们有一种父亲般的关心。" }, { en: "Her paternal grandmother lives nearby.", zh: "她的祖母住在附近。" }],
