  "synchronize": [{ en: "The clocks are synchronized by the network.", zh: "这些钟由网络同步校准。" }, { en: "Synchronize the two watches before the race.", zh: "比赛前把两块表对好。" }],
  "syndrome": [{ en: "The doctor explained the tiredness syndrome to us.", zh: "医生向我们解释了疲劳综合征。" }, { en: "We learned about one syndrome in health class.", zh: "健康课上我们学习了一种综合征。" }],
  "synthesis": [{ en: "Our report is a synthesis of the group's ideas.", zh: "我们的报告是小组想法的综合。" }, { en: "We learned how plants make sugar by synthesis in class.", zh: "课堂上我们学习了植物如何通过合成制造糖。" }],
  "synthesize": [{ en: "Plants synthesize sugar from sunlight.", zh: "植物利用阳光合成糖分。" }, { en: "The team synthesized data from several studies.", zh: "团队综合了多项研究的数据。" }],
