  "systematic": [{ en: "Systematic review helped us remember the units.", zh: "系统的复习帮我们记住了各单元。" }, { en: "We made a systematic plan for the whole term.", zh: "我们为整个学期制定了系统的计划。" }],
  "systematically": [{ en: "We systematically sorted the words by level.", zh: "我们按等级系统地整理了单词。" }, { en: "She systematically checked every answer.", zh: "她有条理地检查了每个答案。" }],
