  "tabulate": [{ en: "Please tabulate the results by class.", zh: "请按班级把结果列成表。" }, { en: "The clerk tabulated the scores.", zh: "职员把分数制成了表格。" }],
  "tack": [{ en: "He used a tack to fix the note on the board.", zh: "他用图钉把便条钉在板上。" }, { en: "We changed tack and tried another plan.", zh: "我们换了思路，尝试另一个方案。" }],
