  "tag": [{ en: "Please add a name tag to your bag.", zh: "请给你的包挂上姓名牌。" }, { en: "We played a fun game of tag at recess.", zh: "课间我们玩了有趣的捉人游戏。" }],
  "tame": [{ en: "The rabbit is tame and eats from my hand.", zh: "这只兔子很温顺，会从我手里吃东西。" }, { en: "It took months to tame the horse.", zh: "驯服这匹马花了好几个月。" }],
  "tan": [{ en: "Her skin turned tan after the summer.", zh: "过了夏天她的皮肤晒成了棕褐色。" }, { en: "He bought a tan bag for school.", zh: "他买了一个棕褐色的书包。" }],
  "tangle": [{ en: "The wires were in a tangle behind the desk.", zh: "桌子后面的电线缠成一团。" }, { en: "Her hair tangled in the wind.", zh: "她的头发被风吹乱了。" }],
