  "tar": [{ en: "Workers poured tar on the road.", zh: "工人们往路面上浇柏油。" }, { en: "The old roof was covered with tar.", zh: "旧屋顶铺着沥青。" }],
  "tariff": [{ en: "We learned how a tariff changes the price of goods.", zh: "我们学习了关税如何改变商品价格。" }, { en: "The tariff table is posted at the station.", zh: "收费表贴在车站。" }],
  "tasteless": [{ en: "The soup was tasteless without salt.", zh: "没放盐的汤没有味道。" }, { en: "That joke was tasteless.", zh: "那个玩笑很没品味。" }],
  "tasty": [{ en: "The soup is tasty and warm on a cold day.", zh: "冷天里这碗汤又暖又可口。" }, { en: "We chose a tasty recipe from the old book.", zh: "我们从旧书里选了一道美味食谱。" }],
  "teamwork": [{ en: "Good teamwork finished the task early.", zh: "良好的协作让任务提前完成。" }, { en: "The project relies on teamwork.", zh: "这个项目依靠团队协作。" }],
  "technician": [{ en: "A technician fixed the projector before the show.", zh: "演出前技术员修好了投影仪。" }, { en: "The lab technician helped with our experiment.", zh: "实验室技术员协助我们做实验。" }],
  "tedious": [{ en: "The long list felt tedious.", zh: "长长的清单让人觉得枯燥。" }],
