  "telegraph": [{ en: "The telegraph changed long-distance news.", zh: "电报改变了远距离传递消息的方式。" }, { en: "They sent word by telegraph.", zh: "他们用电报传了消息。" }],
  "telex": [{ en: "The office sent a telex to the branch.", zh: "办公室给分公司发了电传。" }, { en: "Telex was common before email.", zh: "在电子邮件之前电传很常见。" }],
  "temperament": [{ en: "The little dog has a gentle and happy temperament.", zh: "小狗性情温和愉快。" }, { en: "A patient temperament helps us learn better.", zh: "有耐心的性情帮助我们学得更好。" }],
  "temperamental": [{ en: "She has a temperamental artist.", zh: "她是个喜怒无常的艺术家。" }, { en: "The car is temperamental.", zh: "这辆车性能不稳定。" }],
  "tempo": [{ en: "The music has a slow tempo.", zh: "这首音乐节奏很慢。" }],
