  "thoroughly": [{ en: "We thoroughly cleaned the classroom before the show.", zh: "演出前我们彻底打扫了教室。" }, { en: "Read the instructions thoroughly before you start.", zh: "开始前请仔细阅读说明。" }],
  "thoughtful": [{ en: "It was thoughtful of you to bring an extra pen.", zh: "你想得真周到，带了备用笔。" }, { en: "A thoughtful gift always warms the heart.", zh: "体贴的礼物总是温暖人心。" }],
  "thoughtless": [{ en: "It was thoughtless to forget her birthday.", zh: "忘记她的生日太不体贴了。" }, { en: "A thoughtless remark hurt the guest.", zh: "一句欠考虑的话伤了客人。" }],
