  "thriftless": [{ en: "Thriftless spending emptied his savings.", zh: "挥霍无度花光了他的积蓄。" }, { en: "A thriftless habit is hard to change.", zh: "不节俭的习惯很难改。" }],
  "thrifty": [{ en: "Thrifty families save for hard times.", zh: "节俭的家庭会为困难时期存钱。" }, { en: "She is thrifty with paper and ink.", zh: "她节约纸墨。" }],
  "thrill": [{ en: "The final goal gave us a real thrill.", zh: "最后一球让我们激动不已。" }, { en: "Riding the roller coaster was a thrill for the kids.", zh: "过山车让孩子们兴奋极了。" }],
  "thriller": [{ en: "The movie was a gentle thriller with a happy ending.", zh: "这部电影是一个结局愉快的温和悬疑片。" }, { en: "We watched a heart-fluttering thriller in the class show.", zh: "我们在班级放映中看了一个让人心跳加速的悬疑片。" }],
  "thrive": [{ en: "Plants thrive with water and sunlight.", zh: "植物靠水和阳光茁壮成长。" }, { en: "Kind students thrive in a friendly class.", zh: "友好的班级让友善的学生茁壮成长。" }],
  "throne": [{ en: "The museum keeps an old golden throne.", zh: "博物馆保存着一把旧金王座。" }, { en: "In the play, the queen sits on the throne.", zh: "剧中女王坐在王座上。" }],
  "throng": [{ en: "A throng of fans waited outside the gate.", zh: "一大群粉丝在门外等候。" }, { en: "The market was full of a busy throng.", zh: "市场上挤满了忙碌的人群。" }],
  "thumb": [{ en: "She thumbed through the dictionary quickly.", zh: "她快速翻阅了字典。" }],
